export type SkillLogoSpec =
  | { kind: "brand"; path: string; color?: string }
  | { kind: "glyph"; path: string }
  | null;

// Near-black brands would vanish on the dark theme, so they inherit currentColor.
export function skillLogoSpec(name: string, area: string): SkillLogoSpec {
  const b = SKILL_ICONS[name];
  if (b) {
    const [path, hex] = b;
    const r = parseInt(hex.slice(0, 2), 16), g = parseInt(hex.slice(2, 4), 16), bl = parseInt(hex.slice(4, 6), 16);
    const dark = (0.2126 * r + 0.7152 * g + 0.0722 * bl) / 255 < 0.22;
    return { kind: "brand", path, color: dark ? undefined : `#${hex}` };
  }
  const g = AREA_GLYPHS[area];
  return g ? { kind: "glyph", path: g } : null;
}
